import fs from "node:fs";
import fsp from "node:fs/promises";
import path from "node:path";
import type { Readable } from "node:stream";

/**
 * Tiny storage interface. The app only talks to this, so local disk can be
 * swapped for S3/Supabase later without touching any route.
 */
export interface Storage {
  save(key: string, data: Buffer): Promise<void>;
  open(key: string): Readable;
  remove(key: string): Promise<void>;
}

export class LocalStorage implements Storage {
  constructor(private dir: string) {
    fs.mkdirSync(dir, { recursive: true });
  }
  // Keys are generated by the server (uuid + extension). The basename call is a
  // second line of defence against path traversal.
  private file(key: string) {
    return path.join(this.dir, path.basename(key));
  }
  async save(key: string, data: Buffer) {
    await fsp.writeFile(this.file(key), data);
  }
  open(key: string) {
    return fs.createReadStream(this.file(key));
  }
  async remove(key: string) {
    await fsp.rm(this.file(key), { force: true });
  }
}
